$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest
. (Join-Path $PSScriptRoot '../prepare-noah-pixel-preview.ps1')
. (Join-Path $PSScriptRoot '../test-noah-authored-pixel.ps1')
function RejectAuthored([scriptblock]$Action){$caught=$false;try{& $Action}catch{$caught=$true};if(-not $caught){throw 'Invalid authored preview accepted.'}}
$a=@(Get-NoahAuthoredArguments 'repo with spaces' 'run with spaces' ('a'*40) ('b'*64))
if($a[[Array]::IndexOf($a,'-testFilter')+1] -ne 'Mofumachi.Tests.ExperienceCaptureTests.NoahAuthoredPartsPreviewPreservesState' -or '-mofumachiNoahAuthoredPreview' -notin $a -or '-quit' -in $a){throw 'Wrong single native route.'}
RejectAuthored {Get-NoahAuthoredArguments 'repo' 'out' 'bad' ('b'*64)}
Assert-NoahAuthoredMode "100.5 123 I Unity: MOFUMACHI_NOAH_AUTHORED_MODE authored" 'authored' 100
RejectAuthored {Assert-NoahAuthoredMode "100.5 123 I Unity: MOFUMACHI_NOAH_AUTHORED_MODE current" 'authored' 100}
RejectAuthored {Assert-NoahAuthoredMode "99.5 123 I Unity: MOFUMACHI_NOAH_AUTHORED_MODE authored" 'authored' 100}
$d=Join-Path ([IO.Path]::GetTempPath()) ('mofu-authored-guard-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $d | Out-Null
try{
    RejectAuthored {Read-NoahAuthoredPair $d}
    @{gitRevision=('a'*40);productFingerprint=('b'*64);native_test_passed=$true;source_unchanged=$true;experimental_apk_pair_generated=$true;adopted=$false;error=''} | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $d 'source-info.json') -Encoding UTF8
    foreach($mode in @('current','authored')){
        $apk=Join-Path $d "noah-$mode.apk";[IO.File]::WriteAllText($apk,"synthetic fixture $mode, not a real APK")
        @{scope='experimental-noah-authored-not-release';mode=$mode;apk="noah-$mode.apk";package='com.mofumachi.merge.qa.townlife';gitRevision=('a'*40);productFingerprint=('b'*64);input_sha256=('c'*64);packed_resource_sha256=('d'*64);sha256=(Get-FileHash -LiteralPath $apk -Algorithm SHA256).Hash.ToLowerInvariant();native_capture_method_verified=$true;full_qa_verified=$false;pixel_verified=$false;adopted=$false} | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $d "noah-$mode-build.json") -Encoding UTF8
    }
    $pair=Read-NoahAuthoredPair $d;if($pair.authored.mode -ne 'authored'){throw 'Valid pair rejected.'}
    $meta=Join-Path $d 'noah-authored-build.json';$good=Get-Content -Raw -LiteralPath $meta
    foreach($field in @('mode','package','apk','gitRevision','productFingerprint','input_sha256','packed_resource_sha256','sha256','native_capture_method_verified','full_qa_verified','pixel_verified','adopted')){
        $bad=$good | ConvertFrom-Json
        if($field -eq 'native_capture_method_verified'){$bad.$field=$false}elseif($field -in @('full_qa_verified','pixel_verified','adopted')){$bad.$field=$true}else{$bad.$field='bad'}
        $bad | ConvertTo-Json | Set-Content -LiteralPath $meta -Encoding UTF8;RejectAuthored {Read-NoahAuthoredPair $d}
    }
    Set-Content -LiteralPath $meta -Value $good -Encoding UTF8;$ap=Join-Path $d 'noah-authored.apk';$original=[IO.File]::ReadAllBytes($ap);[IO.File]::AppendAllText($ap,'tampered');RejectAuthored {Read-NoahAuthoredPair $d};[IO.File]::WriteAllBytes($ap,$original)
    $resource=Join-Path $d 'Assets/Mofumachi/Resources/Mofumachi/NoahAuthoredTrial';New-Item -ItemType Directory -Path $resource -Force | Out-Null
    [IO.File]::WriteAllText((Join-Path $resource '.owner'),'some other run');RejectAuthored {Remove-OwnedNoahAuthoredResources $d $d};if(-not(Test-Path -LiteralPath $resource)){throw 'Foreign source removed.'}
    [IO.File]::WriteAllText((Join-Path $resource '.owner'),$d);Remove-OwnedNoahAuthoredResources $d $d;if(Test-Path -LiteralPath $resource){throw 'Owned temporary resources retained.'}
    $source=Join-Path $d 'Assets/Mofumachi/Presentation/Body.cs';New-Item -ItemType Directory -Path (Split-Path -Parent $source) -Force | Out-Null;[IO.File]::WriteAllText($source,'synthetic source')
    $fingerprint=Get-NoahAuthoredSourceFingerprint $d
    New-Item -ItemType Directory -Path $resource -Force | Out-Null;[IO.File]::WriteAllText((Join-Path $resource '.owner'),$d);[IO.File]::WriteAllText((Join-Path $resource 'atlas.png'),'synthetic generated bytes')
    if((Get-NoahAuthoredSourceFingerprint $d) -ne $fingerprint){throw 'Owned generated resources changed the source identity.'}
    [IO.File]::AppendAllText($source,' changed');if((Get-NoahAuthoredSourceFingerprint $d) -eq $fingerprint){throw 'Changed source escaped fingerprint.'}
    Remove-OwnedNoahAuthoredResources $d $d
    function Invoke-CheckedNative($Executable,[string[]]$NativeArguments){
        if('devices' -in $NativeArguments){return "SERIAL`tdevice"}
        if('getprop' -in $NativeArguments){return 'Pixel 3a'}
        if('date' -in $NativeArguments){return '100'}
        if('crash' -in $NativeArguments){return 'synthetic crash buffer, not device evidence'}
        throw 'Synthetic process/memory unavailable'
    }
    function Invoke-PixelInstall {throw 'Synthetic launch failure'}
    $caught='';try{Invoke-NoahAuthoredPixel $d 'authored' 0 'SERIAL' (Join-Path $d 'sdk/platform-tools/adb.exe')}catch{$caught=$_.Exception.Message}
    if($caught -ne 'Synthetic launch failure'){throw "Original launch error lost: $caught"}
    $latest=Get-ChildItem -LiteralPath $d -Directory | Where-Object Name -like 'pixel-*' | Sort-Object Name | Select-Object -Last 1
    $result=Get-Content -Raw -LiteralPath (Join-Path $latest.FullName 'noah-authored-pixel.json') | ConvertFrom-Json
    if($result.installation_verified -or $result.renderer_mode_verified -or $null -ne $result.surface_metrics -or $null -ne $result.same_process -or $result.adopted){throw 'Startup failure became success or fake measurements.'}
    if(-not(Test-Path -LiteralPath ($latest.FullName+'.zip'))){throw 'Launch diagnostic ZIP missing.'}
    function Compress-Archive {throw 'Synthetic archive failure'}
    $caught='';try{Invoke-NoahAuthoredPixel $d 'authored' 0 'SERIAL' (Join-Path $d 'sdk/platform-tools/adb.exe')}catch{$caught=$_.Exception.Message}
    if($caught -ne 'Synthetic launch failure'){throw 'Archive error masked original launch failure.'}
    Remove-Item Function:Compress-Archive
    function Invoke-PixelInstall {}
    function Read-Host {return 'unknown'}
    function Wait-NoahAuthoredSurface {return 'synthetic Unity SurfaceView'}
    function Invoke-CheckedNative($Executable,[string[]]$NativeArguments){
        if('devices' -in $NativeArguments){return "SERIAL`tdevice"}
        if('getprop' -in $NativeArguments){return 'Pixel 3a'}
        if('date' -in $NativeArguments){return '100'}
        if('Unity' -in $NativeArguments){return '100.5 123 I Unity: MOFUMACHI_NOAH_AUTHORED_MODE authored'}
        if('meminfo' -in $NativeArguments){return 'TOTAL PSS: 12345'}
        if('pidof' -in $NativeArguments){return '123'}
        if('crash' -in $NativeArguments){return 'synthetic raw crash buffer'}
        throw 'Unexpected synthetic call'
    }
    $success=Invoke-NoahAuthoredPixel $d 'authored' 0 'SERIAL' (Join-Path $d 'sdk/platform-tools/adb.exe')
    $result=Get-Content -Raw -LiteralPath (Join-Path $success 'noah-authored-pixel.json') | ConvertFrom-Json
    if(-not $result.installation_verified -or -not $result.renderer_mode_verified -or $result.pid_start -ne '123' -or -not $result.same_process -or $result.total_pss_start_kb -ne 12345 -or $result.adopted -or $result.pixel_verified){throw 'Synthetic success lost attribution/data or claimed device acceptance.'}
    Write-Host 'Authored route guards passed: exact native method, missing/invalid/mismatched APK pairs and ownership cleanup. Synthetic files only; no Unity or device contacted.'
}finally{Remove-Item -LiteralPath $d -Recurse -Force}
